95: /* 物业管理区域搜索：下拉浮层不挤占下方字段 */
96: .complex-control{position:relative}
97: .complex-picked{display:flex;align-items:center;justify-content:space-between;margin-top:8px}
98: .complex-picked-text{font-size:15px;color:#1a6fd6}
99: .complex-picked-clear{font-size:15px;color:#999;padding:2px 6px}
100: .complex-dropdown{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:18;border:1px solid #e6e6e6;border-radius:8px;max-height:240px;overflow-y:auto;background:#fff;box-shadow:0 8px 24px #0000001f}
101: .complex-option{padding:10px 12px;font-size:16px;color:#333;border-bottom:1px solid #f2f2f2}
102: .complex-option:last-child{border-bottom:none}
103: .complex-option.chosen{color:#1a6fd6;background:#f2f7ff}
104: .complex-option.muted{color:#999}
105: .field-label,.upload-label{font-size:15px;line-height:20px;display:block}
106: .field-required{color:#ba1a1a}
107: .field-input,.field-textarea{background:var(--c-fill);border-radius:6px;padding:0 8px;font-size:15px;width:100%;display:block}
108: .field-input{height:56px;line-height:56px;display:flex;align-items:center}
109: /* 输入框中的原生 input 需继承容器尺寸 */
110: .field-input > input{width:100%;height:54px;line-height:54px;display:block;background:transparent;border:0;font-size:15px;color:var(--c-text);padding:0}
111: .field-input > input::placeholder{color:var(--c-text-3)}
112: .field-textarea-wrap{position:relative;background:var(--c-fill);border-radius:6px;padding:8px 8px 20px}
113: .field-textarea-wrap .field-textarea.inner{background:transparent;padding:0;height:76px;min-height:76px;border-radius:0;line-height:20px;font-size:15px}
114: .field-count{position:absolute;right:8px;bottom:3px;font-size:13px;line-height:15px;color:var(--c-text-3)}
115: .date-icon{width:16px;height:16px;flex:none}
116: .field-textarea{height:92px;min-height:92px;line-height:21px;resize:vertical}
117: .field-counter{font-size:13px;color:var(--c-text-2);line-height:16px;text-align:center;display:block}
