119: .stepper{height:40px;border-radius:6px;background:var(--c-fill);padding:4px 6px;display:flex;align-items:center;gap:6px}
120: .stepper-button{width:36px;height:30px;border-radius:6px;background:var(--c-fill-strong);font-size:19px;line-height:1;display:flex;align-items:center;justify-content:center;color:var(--c-text)}
121: .stepper-button.disabled{opacity:.45}
122: .stepper-value{flex:1;text-align:center;color:var(--c-text-3);font-size:16px}
123: .choices{display:flex;gap:8px}
124: .choice{flex:1;text-align:center;background:var(--c-fill);border-radius:6px;height:32px;color:var(--c-text-2);font-size:16px;display:flex;align-items:center;justify-content:center}

